(async()=>{let browser,p;try{assert(['--red','--green','--perspective','--diagnostics','--rollback','--session'].some(flag=>process.argv.includes(flag)),'Requires root native baseline clearance');await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+server.address().port;browser=await chromium.launch({channel:'msedge',headless:true});const context=await browser.newContext({viewport:{width:1440,height:1000}});context.on('page',q=>{q.on('pageerror',e=>proof.pageErrors.push(e.message));q.on('console',m=>{if(m.type()==='error')proof.consoleErrors.push(m.text());});q.on('request',r=>{if(/^https?:/.test(r.url())&&!r.url().startsWith(origin+'/'))proof.externalRequests.push(r.url());});});p=await context.newPage();await p.goto(origin+'/editor/index.html');await p.waitForFunction(()=>typeof serializeProject==='function');if(await p.locator('#first-run-skip').isVisible())await p.locator('#first-run-skip').click();if(process.argv.includes('--session'))await session(p,context,origin);else if(process.argv.includes('--rollback'))await rollback(p,context,origin);else if(process.argv.includes('--diagnostics'))await diagnostics(p);else if(process.argv.includes('--perspective'))await perspective(p,context,origin);else if(process.argv.includes('--green'))await green(p,context,origin);else await red(p);proof.finalFingerprint=fingerprint();assert.equal(proof.finalFingerprint,proof.fingerprint);assert.deepStrictEqual(proof.pageErrors,[]);assert.deepStrictEqual(proof.consoleErrors,[]);assert.deepStrictEqual(proof.externalRequests,[]);}catch(e){proof.status=proof.pageErrors.length?'PRODUCT_BROWSER_ERROR':'AUTOMATION_OR_FIXTURE_OR_PRODUCT_ASSERTION';proof.failure=e.stack;await p?.screenshot({path:path.join(dir,'failure.png')}).catch(()=>{});process.exitCode=1;}finally{proof.endedAt=new Date().toISOString();fs.writeFileSync(path.join(dir,'proof.json'),JSON.stringify(proof,null,2));await browser?.close();if(server.listening)await new Promise(r=>server.close(r));console.log(JSON.stringify({runId,status:proof.status,steps:proof.steps.length,failure:proof.failure,closed:true}));}})();
